/*
 * A262115  Irregular triangle read by rows: row b (b >= 2) gives periodic
 *          part of digits of the base-b expansion of 1/7.
 * https://oeis.org/A262115
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn, base, tabf, easy
 * Formula:   a(n) = nth digit of the concatenation of periodic expansions of
 *            1/7 in bases b = 2,3,4,..., offset 2 (a(2) is the first digit).
 *            Each expansion is generated by the long‑division algorithm with
 *            remainder r = 1; digit = (r*b)/7; r = (r*b)%7. For bases
 *            divisible by 7 the expansion terminates after th...
 * Range:     u8 n <= 940, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

static seq_t *seq_cache = NULL;    /* 0‑based array, indices 0 and 1 unused */
static size_t cache_len = 0;       /* number of elements stored (>= cache_len) */
static size_t cache_cap = 0;
static idx_t next_base = 2;        /* next base to generate digits for */

/* Ensure the cache has capacity for at least 'need' elements.  */
static void ensure_capacity(size_t need)
{
    if (need <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap : 64;
    while (new_cap < need)
        new_cap *= 2;
    seq_t *new_buf = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
    seq_cache = new_buf;
    cache_cap = new_cap;
}

/* Generate digits for base 'b' and append them to the cache.  */
static void generate_base(idx_t b)
{
    uint64_t rem = 1;                 /* remainder of the division */
    int terminate = (b % 7 == 0);     /* if true, stop after remainder 0 */
    for (;;)
    {
        seq_t digit = (seq_t)((rem * b) / 7);   /* current digit */
        rem       = (rem * b) % 7;             /* next remainder */
        /* Append digit to sequence */
        ensure_capacity(cache_len + 1);
        seq_cache[cache_len] = digit;
        cache_len++;

        /* stop conditions */
        if (terminate)
        {
            if (rem == 0)
                break;                     /* division finished */
        }
        else
        {
            if (rem == 1)
                break;                     /* period finished */
        }
    }
}

/* Expand the sequence until index 'n' is reachable.  */
static void expand_up_to(idx_t n)
{
    while (cache_len <= (size_t)n)
    {
        generate_base(next_base);
        next_base++;
    }
}

seq_t a(idx_t n)
{
    if (n < 2)
        return 0;  /* behaviour for n < 2 is unspecified */
    /* Start cache with dummy entries for indices 0 and 1 */
    if (cache_len == 0)
    {
        ensure_capacity(4);
        seq_cache[0] = seq_cache[1] = (seq_t)0;
        cache_len = 2;
    }
    expand_up_to(n);
    return seq_cache[(size_t)n];
}
